            game.addForest(forest5);
        }

        // Additional forests near lakes
        if (!overlaps(0, 35, 3, 2, cityRects)) {
            Forest forest6 = new Forest("forest_5", "Willow Grove", 0, 35, 3, 2);
            game.addForest(forest6);
        }

