        }

        if (!overlaps(41, 10, 3, 3, cityRects)) {
            Forest forest12 = new Forest("forest_11", "River Oaks", 41, 10, 3, 3);
            game.addForest(forest12);
        }

        if (!overlaps(41, 20, 2, 2, cityRects)) {
            Forest forest13 = new Forest("forest_12", "Water Birches", 41, 20, 2, 2);
            game.addForest(forest13);
        }

        if (!overlaps(41, 40, 3, 2, cityRects)) {
            Forest forest14 = new Forest("forest_13", "Shore Maples", 41, 40, 3, 2);
            game.addForest(forest14);
        }

        if (!overlaps(41, 70, 2, 3, cityRects)) {
            Forest forest15 = new Forest("forest_14", "Bay Cedars", 41, 70, 2, 3);
            game.addForest(forest15);
        }

        if (!overlaps(30, 0, 2, 4, cityRects)) {
            Forest forest16 = new Forest("forest_15", "Coastal Pines", 30, 0, 2, 4);
            game.addForest(forest16);
        }

        return game;
    }

    private City createCityFromTemplate(String id, CityTemplate template, int startX, int startY) {
        City city = new City(id, template.getName(), startX, startY, template.getWidth(), template.getHeight());

        for (int y = 0; y < template.getHeight(); y++) {
            for (int x = 0; x < template.getWidth(); x++) {
                int worldX = startX + x;
                int worldY = startY + y;
                char symbol = template.getTileSymbol(x, y);

                switch (symbol) {
                    case 'B' -> city.addBuildingTile(worldX, worldY);
                    case '.' -> city.addEmptyTile(worldX, worldY);
                    case 'H' -> city.addRoadTile(worldX, worldY, City.CityRoadType.HORIZONTAL);
                    case 'V' -> city.addRoadTile(worldX, worldY, City.CityRoadType.VERTICAL);
                    case 'X' -> city.addRoadTile(worldX, worldY, City.CityRoadType.CROSSROAD);
                }
            }
        }

        for (Position p : city.getEmptyTiles()) {
            if (p.getX() == startX ||
                    p.getX() == startX + template.getWidth() - 1 ||
                    p.getY() == startY ||
                    p.getY() == startY + template.getHeight() - 1) {
                city.addEntrance(p.getX(), p.getY());
            }
        }

        return city;
    }


    private int[] findFreePosition(int mapW, int mapH, int entityW, int entityH, List<int[]> occupied) {
        if (mapW - entityW - 2 <= 0 || mapH - entityH - 2 <= 0) {
            return null;
        }

        for (int attempt = 0; attempt < 200; attempt++) {
            int x = 1 + rng.nextInt(Math.max(1, mapW - entityW - 2));
            int y = 1 + rng.nextInt(Math.max(1, mapH - entityH - 2));

            if (!overlaps(x, y, entityW, entityH, occupied)) {
                return new int[]{x, y};
            }
        }

        return null;
    }

    private boolean overlaps(int x, int y, int w, int h, List<int[]> occupied) {
        for (int[] rect : occupied) {
            int rx = rect[0];
            int ry = rect[1];
            int rw = rect[2];
            int rh = rect[3];

            if (x < rx + rw && x + w > rx && y < ry + rh && y + h > ry) {
                return true;
            }
        }
        return false;
    }
}

package model.service;

import model.GameState;
import model.Road;
import model.Stop;
import model.Tile;
import model.enums.TileType;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;

/**
 * SaveManager — handles persisting and loading the state of the game.
 * Extracted from the original MapDemo class.
 */
public class SaveManager {

    private static final Path SAVE_DIR = Path.of(System.getProperty("user.home"), ".haulyea");
    private static final Path SAVE_FILE = SAVE_DIR.resolve("savegame.txt");

    /**
     * Saves the provided Game state to ~/.haulyea/savegame.txt.
     * Currently ignores the slot parameter to stick to the default behavior.
     *
     * @param state the game state to save
     * @param slot save slot index (reserved for future multi-save support)
     */
    public void save(GameState state, int slot) {
        model.Game game = state.getMap();
        StringBuilder content = new StringBuilder();
        content.append("# Haul Yea Save\n");
        content.append("savedAt=")
                .append(LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME))
                .append('\n');
        content.append("worldName=").append(game.getWorldName()).append('\n');
        content.append("width=").append(game.getWidth()).append('\n');
        content.append("height=").append(game.getHeight()).append('\n');
        content.append("roads=").append(game.getRoads().size()).append('\n');

        content.append("[roadList]\n");
        for (Road road : game.getRoads()) {
            content.append(road.getId()).append(',')
                    .append(road.getPosition().getX()).append(',')
                    .append(road.getPosition().getY()).append(',')
                    .append(road.getType())
                    .append('\n');
        }

        content.append("stops=").append(game.getStops().size()).append('\n');
        content.append("[stopList]\n");
        for (Stop stop : game.getStops()) {
            content.append(stop.getId()).append(',')
                    .append(stop.getPosition().getX()).append(',')
                    .append(stop.getPosition().getY()).append(',')
                    .append(stop.getName())
                    .append('\n');
        }

        content.append("[tileTypes]\n");
        for (int y = 0; y < game.getHeight(); y++) {
            for (int x = 0; x < game.getWidth(); x++) {
                Tile tile = game.getTile(x, y);
                TileType type = tile == null ? TileType.EMPTY : tile.getType();
                content.append(type.name());
                if (x < game.getWidth() - 1) {
                    content.append(',');
                }
            }
            content.append('\n');
        }

        try {
            Files.createDirectories(SAVE_DIR);
            Files.writeString(SAVE_FILE, content);
            System.out.println("[SaveManager] Game saved: " + SAVE_FILE);
        } catch (IOException ex) {
            System.err.println("[SaveManager] Failed to save game: " + ex.getMessage());
            ex.printStackTrace();
        }
    }

    /**
     * Stub for loading a game.
     * @param slot save slot index
     * @return the loaded Game, or null if it failed
     */
    public GameState load(int slot) {
        System.out.println("[SaveManager] load() not yet implemented");
        return null;
    }
}

package model.service;

import model.GameState;
import model.Road;
import model.Stop;
import model.Tile;
import model.enums.TileType;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;

/**
 * SaveManager — handles persisting and loading the state of the game.
 * Extracted from the original MapDemo class.
 */
public class SaveManager {

    private static final Path SAVE_DIR = Path.of(System.getProperty("user.home"), ".haulyea");
    private static final Path SAVE_FILE = SAVE_DIR.resolve("savegame.txt");

    /**
     * Saves the provided Game state to ~/.haulyea/savegame.txt.
     * Currently ignores the slot parameter to stick to the default behavior.
     *
     * @param state the game state to save
     * @param slot save slot index (reserved for future multi-save support)
     */
    public void save(GameState state, int slot) {
        model.Game game = state.getMap();
        StringBuilder content = new StringBuilder();
        content.append("# Haul Yea Save\n");
        content.append("savedAt=")
                .append(LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME))
                .append('\n');
        content.append("worldName=").append(game.getWorldName()).append('\n');
        content.append("width=").append(game.getWidth()).append('\n');
        content.append("height=").append(game.getHeight()).append('\n');
        content.append("roads=").append(game.getRoads().size()).append('\n');

        content.append("[roadList]\n");
        for (Road road : game.getRoads()) {
            content.append(road.getId()).append(',')
                    .append(road.getPosition().getX()).append(',')
                    .append(road.getPosition().getY()).append(',')
                    .append(road.getType())
                    .append('\n');
        }

        content.append("stops=").append(game.getStops().size()).append('\n');
        content.append("[stopList]\n");
        for (Stop stop : game.getStops()) {
            content.append(stop.getId()).append(',')
                    .append(stop.getPosition().getX()).append(',')
                    .append(stop.getPosition().getY()).append(',')
                    .append(stop.getName())
                    .append('\n');
        }

        content.append("[tileTypes]\n");
        for (int y = 0; y < game.getHeight(); y++) {
            for (int x = 0; x < game.getWidth(); x++) {
                Tile tile = game.getTile(x, y);
                TileType type = tile == null ? TileType.EMPTY : tile.getType();
                content.append(type.name());
                if (x < game.getWidth() - 1) {
                    content.append(',');
                }
            }
            content.append('\n');
        }

        try {
            Files.createDirectories(SAVE_DIR);
            Files.writeString(SAVE_FILE, content);
            System.out.println("[SaveManager] Game saved: " + SAVE_FILE);
        } catch (IOException ex) {
            System.err.println("[SaveManager] Failed to save game: " + ex.getMessage());
            ex.printStackTrace();
        }
    }

    /**
     * Loads a game from the given slot.
     * @param slot save slot index
     * @return the loaded GameState, or null if it failed
     */
    public GameState load(int slot) {
        try {
            Path file = SAVE_FILE;
            if (!Files.exists(file)) {
                System.err.println("[SaveManager] Save file does not exist: " + file);
                return null;
            }

            List<String> lines = Files.readAllLines(file);
            if (lines.isEmpty()) {
                System.err.println("[SaveManager] Save file is empty");
                return null;
            }

            String worldName = null;
            int width = 0, height = 0;
            List<Road> roads = new ArrayList<>();
            List<Stop> stops = new ArrayList<>();
            TileType[][] tileTypes = null;

            int section = 0; // 0: header, 1: roadList, 2: stopList, 3: tileTypes
            int roadCount = 0, stopCount = 0;
            int y = 0;

            for (String line : lines) {
                line = line.trim();
                if (line.isEmpty() || line.startsWith("#")) continue;

                if (line.startsWith("worldName=")) {
                    worldName = line.substring(10);
                } else if (line.startsWith("width=")) {
                    width = Integer.parseInt(line.substring(6));
                } else if (line.startsWith("height=")) {
                    height = Integer.parseInt(line.substring(7));
                } else if (line.startsWith("roads=")) {
                    roadCount = Integer.parseInt(line.substring(6));
                } else if (line.startsWith("stops=")) {
                    stopCount = Integer.parseInt(line.substring(6));
                } else if (line.equals("[roadList]")) {
                    section = 1;
                } else if (line.equals("[stopList]")) {
                    section = 2;
                } else if (line.equals("[tileTypes]")) {
                    section = 3;
                    tileTypes = new TileType[height][width];
                } else {
                    if (section == 1 && roads.size() < roadCount) {
                        String[] parts = line.split(",");
                        if (parts.length == 4) {
                            String id = parts[0];
                            int x = Integer.parseInt(parts[1]);
                            int y = Integer.parseInt(parts[2]);
                            Road.RoadType type = Road.RoadType.valueOf(parts[3]);
                            roads.add(new Road(id, x, y, type));
                        }
                    } else if (section == 2 && stops.size() < stopCount) {
                        String[] parts = line.split(",");
                        if (parts.length == 4) {
                            String id = parts[0];
                            int x = Integer.parseInt(parts[1]);
                            int y = Integer.parseInt(parts[2]);
                            String name = parts[3];
                            stops.add(new Stop(id, x, y, name));
                        }
                    } else if (section == 3 && y < height) {
                        String[] types = line.split(",");
                        for (int x = 0; x < width && x < types.length; x++) {
                            tileTypes[y][x] = TileType.valueOf(types[x]);
                        }
                        y++;
                    }
                }
            }

            if (worldName == null || width == 0 || height == 0 || tileTypes == null) {
                System.err.println("[SaveManager] Invalid save file format");
                return null;
            }

            // Create Game
            Game game = new Game(width, height);
            game.setWorldName(worldName);

            // Set tile types
            for (int yy = 0; yy < height; yy++) {
                for (int xx = 0; xx < width; xx++) {
                    Tile tile = game.getTile(xx, yy);
                    if (tile != null && tileTypes[yy][xx] != null) {
                        tile.setType(tileTypes[yy][xx]);
                    }
                }
            }

            // Add roads
            for (Road road : roads) {
                game.getRoads().add(road);
            }

            // Add stops
            for (Stop stop : stops) {
                game.getStops().add(stop);
            }

            // Create GameState with default Player
            Player player = new Player("Player 1", 100000);
            GameState state = new GameState(game, player);

            System.out.println("[SaveManager] Game loaded: " + SAVE_FILE);
            return state;

        } catch (Exception ex) {
            System.err.println("[SaveManager] Failed to load game: " + ex.getMessage());
            ex.printStackTrace();
            return null;
        }
    }
}

package controller;

import model.GameState;
import model.service.SimulationEngine;
import javafx.animation.AnimationTimer;
import view.PopupTheme;
/**
 * SimulationController
 *
 * Manages the simulation lifecycle:
 *   - Play / Pause
 *   - Speed control (1×, 2×, 4×)
 *   - Saving the current game to a slot
 *
 * In a future issue this controller will drive a JavaFX AnimationTimer
 * that calls SimulationEngine.tick(state, dt) on every frame.
 *
 * It fires an onStateChanged callback after each action so the HUD
 * (speed indicator, pause icon) can refresh without the controller
 * touching JavaFX directly.
 */
public class SimulationController {

    /** Matches the TimeSpeed enum in the UML (currently stored in GameSpeed). */
    public enum Speed {
        PAUSED(0, "⏸"),
        X1(1,    "▶  1×"),
        X2(2,    "▶▶ 2×"),
        X4(4,    "▶▶▶ 4×");

        public final int multiplier;
        public final String label;

        Speed(int multiplier, String label) {
            this.multiplier = multiplier;
            this.label = label;
        }

        /** Cycles: PAUSED → X1 → X2 → X4 → PAUSED */
        public Speed next() {
            return switch (this) {
                case PAUSED -> X1;
                case X1     -> X2;
                case X2     -> X4;
                case X4     -> PAUSED;
            };
        }
    }

    private final GameState state;
    private Speed      speed   = Speed.PAUSED;
    private boolean    running = false;
    private boolean hasUnsavedChanges = false;

    private final SimulationEngine engine = new SimulationEngine();
    private AnimationTimer timer;
    private long lastTime = 0;

    // Registered by the View (HudPanel) to refresh speed/pause display
    private Runnable onStateChanged;
    private Runnable onBankrupt;

    public SimulationController(GameState state) {
        this.state = state;

        this.timer = new AnimationTimer() {
            @Override
            public void handle(long now) {
                if (lastTime == 0) {
                    lastTime = now;
                    return;
                }

                // Elapsed physical time in seconds
                double elapsedSeconds = (now - lastTime) / 1_000_000_000.0;
                lastTime = now;

                if (speed != Speed.PAUSED) {
                    double dt = elapsedSeconds * speed.multiplier;
                    engine.tick(SimulationController.this.state, dt);
                    notifyView();

                    if (state.getPlayer().getLedger().getCurrentCapital() < 0) {
                        pause();
                        if (onBankrupt != null) onBankrupt.run();
                    }
                }
            }
        };
    }

    public void setOnStateChanged(Runnable callback) { this.onStateChanged = callback; }
    public void setOnBankrupt(Runnable callback)      { this.onBankrupt = callback; }

    // -----------------------------------------------------------------------
    // Simulation control
    // -----------------------------------------------------------------------

    /**
     * Starts (or resumes) the simulation.
     * If currently paused, switches to 1× speed.
     */
    public void play() {
        if (speed == Speed.PAUSED) {
            speed = Speed.X1;
        }
        running = true;
        System.out.println("[SimulationController] play() — " + speed.label);
        lastTime = 0;
        timer.start();
        notifyView();
    }

    /**
     * Pauses the simulation.
     */
    public void pause() {
        running = false;
        speed   = Speed.PAUSED;
        System.out.println("[SimulationController] pause()");
        timer.stop();
        notifyView();
    }

    /**
     * Cycles through PAUSED → 1× → 2× → 4× → PAUSED.
     * Convenient for a single speed-toggle button.
     */
    public void cycleSpeed() {
        speed   = speed.next();
        running = speed != Speed.PAUSED;
        System.out.println("[SimulationController] speed -> " + speed.label);

        if (running) {
            lastTime = 0;
            timer.start();
        } else {
            timer.stop();
        }

        notifyView();
    }

    /**
     * Sets a specific speed directly.
     *
     * @param newSpeed desired speed (use Speed.PAUSED to pause)
     */
    public void setSpeed(Speed newSpeed) {
        this.speed   = newSpeed;
        this.running = newSpeed != Speed.PAUSED;
        System.out.println("[SimulationController] setSpeed -> " + newSpeed.label);

        if (running) {
            lastTime = 0;
            timer.start();
        } else {
            timer.stop();
        }

        notifyView();
    }

    // -----------------------------------------------------------------------
    // Save
    // -----------------------------------------------------------------------

    /**
     * Saves the game to the given slot.
     *
     * @param slot save-slot index (0-based)
     */
    public void saveGame(int slot) {
        new model.service.SaveManager().save(state, slot);
        clearUnsavedChanges();
        // Show success dialogue
        javafx.scene.control.Alert alert = PopupTheme.createAlert(
                javafx.scene.control.Alert.AlertType.INFORMATION,
                "Save Game",
                null,
                "Game saved successfully!");
        alert.showAndWait();

    }

    /**
     * Marks that there are unsaved changes.
     */
    public void markUnsavedChanges() {
        hasUnsavedChanges = true;
    }

    /**
     * Checks if there are unsaved changes.
     */
    public boolean hasUnsavedChanges() {
        return hasUnsavedChanges;
    }

    /**
     * Clears the unsaved changes flag (called after saving).
     */
    public void clearUnsavedChanges() {
        hasUnsavedChanges = false;
    }

    // -----------------------------------------------------------------------
    // Getters for the HUD
    // -----------------------------------------------------------------------

    public boolean isRunning() { return running; }
    public Speed   getSpeed()  { return speed; }

    /** Clears saved tile-progress for a vehicle so it restarts cleanly. */
    public void resetVehicle(String vehicleId) {
        engine.resetVehicle(vehicleId);
    }

    // -----------------------------------------------------------------------
    // Internal
    // -----------------------------------------------------------------------

    private void notifyView() {
        if (onStateChanged != null) {
            onStateChanged.run();
        }
    }
}

