import javafx.scene.Node;
import javafx.scene.control.Alert;
import javafx.scene.control.Button;
import javafx.scene.control.ButtonBar;
import javafx.scene.control.ButtonType;
import javafx.scene.control.DialogPane;
import javafx.scene.control.Label;

public final class PopupTheme {

    public static final String ROOT_STYLE =
            "-fx-background-color: linear-gradient(to right, #d9edf9, #f7dcc0);" +
                    "-fx-border-color: #d8c3a8;" +
                    "-fx-border-width: 1;" +
                    "-fx-border-radius: 16;" +
                    "-fx-background-radius: 16;";

    public static final String HEADER_STYLE =
            "-fx-background-color: rgba(255,255,255,0.55);" +
                    "-fx-border-color: rgba(0,0,0,0.08);" +
                    "-fx-border-width: 0 0 1 0;" +
                    "-fx-background-radius: 16 16 0 0;";

    public static final String TITLE_STYLE =
            "-fx-font-size: 24px;" +
                    "-fx-font-weight: bold;" +
                    "-fx-text-fill: #2f2a24;";

    public static final String LABEL_STYLE =
            "-fx-font-size: 14px;" +
                    "-fx-text-fill: #4b3a2d;";

    public static final String SUBTEXT_STYLE =
            "-fx-font-size: 13px;" +
                    "-fx-text-fill: #7b6553;";

    public static final String CARD_STYLE =
            "-fx-background-color: rgba(255,255,255,0.58);" +
                    "-fx-border-color: rgba(0,0,0,0.08);" +
                    "-fx-border-radius: 12;" +
                    "-fx-background-radius: 12;" +
                    "-fx-padding: 18;";

    public static final String PRIMARY_BUTTON_STYLE =
            "-fx-background-color: #b83a3a;" +
                    "-fx-text-fill: white;" +
                    "-fx-font-size: 14px;" +
                    "-fx-font-weight: bold;" +
                    "-fx-background-radius: 10;" +
                    "-fx-padding: 10 22;" +
                    "-fx-cursor: hand;";

    public static final String SECONDARY_BUTTON_STYLE =
            "-fx-background-color: #9aab64;" +
                    "-fx-text-fill: white;" +
                    "-fx-font-size: 14px;" +
                    "-fx-font-weight: bold;" +
                    "-fx-background-radius: 10;" +
                    "-fx-padding: 10 22;" +
                    "-fx-cursor: hand;";

    public static final String MUTED_BUTTON_STYLE =
            "-fx-background-color: #8f857a;" +
                    "-fx-text-fill: white;" +
                    "-fx-font-size: 14px;" +
                    "-fx-font-weight: bold;" +
                    "-fx-background-radius: 10;" +
                    "-fx-padding: 10 22;" +
                    "-fx-cursor: hand;";

    public static final String FIELD_STYLE =
            "-fx-font-size: 14px;" +
                    "-fx-text-fill: #3d3026;" +
                    "-fx-background-color: rgba(255,255,255,0.92);" +
                    "-fx-border-color: rgba(0,0,0,0.10);" +
                    "-fx-border-radius: 10;" +
                    "-fx-background-radius: 10;" +
                    "-fx-padding: 8 10;";

    private PopupTheme() {}

    public static Alert createAlert(Alert.AlertType type, String title, String header, String content, ButtonType... buttons) {
        Alert alert = new Alert(type);
        alert.setTitle(title);
        alert.setHeaderText(header);
        alert.setContentText(content);
        if (buttons != null && buttons.length > 0) {
            alert.getButtonTypes().setAll(buttons);
        }
        styleAlert(alert);
        return alert;
    }

    public static void styleAlert(Alert alert) {
        DialogPane pane = alert.getDialogPane();
        pane.setGraphic(null);
        pane.setStyle(ROOT_STYLE);

        alert.setOnShown(e -> {
            Node header = pane.lookup(".header-panel");
            if (header != null) header.setStyle(HEADER_STYLE);

            Node headerLabel = pane.lookup(".header-panel .label");
            if (headerLabel instanceof Label label) label.setStyle(TITLE_STYLE.replace("24px", "20px"));

            Node contentLabel = pane.lookup(".content.label");
            if (contentLabel instanceof Label label) label.setStyle(LABEL_STYLE);

            for (ButtonType bt : pane.getButtonTypes()) {
                Node node = pane.lookupButton(bt);
                if (node instanceof Button button) {
                    ButtonBar.ButtonData data = bt.getButtonData();
                    if (bt == ButtonType.CANCEL || data == ButtonBar.ButtonData.CANCEL_CLOSE) {
                        button.setStyle(MUTED_BUTTON_STYLE);
                    } else if (data == ButtonBar.ButtonData.OK_DONE || data == ButtonBar.ButtonData.YES || data == ButtonBar.ButtonData.APPLY) {
                        button.setStyle(SECONDARY_BUTTON_STYLE);
                    } else {
                        button.setStyle(PRIMARY_BUTTON_STYLE);
                    }
                }
            }
        });
    }
}

package view;

import javafx.scene.Node;
import javafx.scene.control.Alert;
import javafx.scene.control.Button;
import javafx.scene.control.ButtonBar;
import javafx.scene.control.ButtonType;
import javafx.scene.control.DialogPane;
import javafx.scene.control.Label;
import javafx.stage.Modality;
import javafx.stage.Stage;
import javafx.stage.Window;

import java.util.Optional;

public final class PopupTheme {

    public static final String ROOT_STYLE =
            "-fx-background-color: linear-gradient(to right, #d9edf9, #f7dcc0);" +
                    "-fx-border-color: #d8c3a8;" +
                    "-fx-border-width: 1;" +
                    "-fx-border-radius: 16;" +
                    "-fx-background-radius: 16;";

    public static final String HEADER_STYLE =
            "-fx-background-color: rgba(255,255,255,0.55);" +
                    "-fx-border-color: rgba(0,0,0,0.08);" +
                    "-fx-border-width: 0 0 1 0;" +
                    "-fx-background-radius: 16 16 0 0;";

    public static final String TITLE_STYLE =
            "-fx-font-size: 24px;" +
                    "-fx-font-weight: bold;" +
                    "-fx-text-fill: #2f2a24;";

    public static final String LABEL_STYLE =
            "-fx-font-size: 14px;" +
                    "-fx-text-fill: #4b3a2d;";

    public static final String SUBTEXT_STYLE =
            "-fx-font-size: 13px;" +
                    "-fx-text-fill: #7b6553;";

    public static final String CARD_STYLE =
            "-fx-background-color: rgba(255,255,255,0.58);" +
                    "-fx-border-color: rgba(0,0,0,0.08);" +
                    "-fx-border-radius: 12;" +
                    "-fx-background-radius: 12;" +
                    "-fx-padding: 18;";

    public static final String PRIMARY_BUTTON_STYLE =
            "-fx-background-color: #b83a3a;" +
                    "-fx-text-fill: white;" +
                    "-fx-font-size: 14px;" +
                    "-fx-font-weight: bold;" +
                    "-fx-background-radius: 10;" +
                    "-fx-padding: 10 22;" +
                    "-fx-cursor: hand;";

    public static final String SECONDARY_BUTTON_STYLE =
            "-fx-background-color: #9aab64;" +
                    "-fx-text-fill: white;" +
                    "-fx-font-size: 14px;" +
                    "-fx-font-weight: bold;" +
                    "-fx-background-radius: 10;" +
                    "-fx-padding: 10 22;" +
                    "-fx-cursor: hand;";

    public static final String MUTED_BUTTON_STYLE =
            "-fx-background-color: #8f857a;" +
                    "-fx-text-fill: white;" +
                    "-fx-font-size: 14px;" +
                    "-fx-font-weight: bold;" +
                    "-fx-background-radius: 10;" +
                    "-fx-padding: 10 22;" +
                    "-fx-cursor: hand;";

    public static final String FIELD_STYLE =
            "-fx-font-size: 14px;" +
                    "-fx-text-fill: #3d3026;" +
                    "-fx-background-color: rgba(255,255,255,0.92);" +
                    "-fx-border-color: rgba(0,0,0,0.10);" +
                    "-fx-border-radius: 10;" +
                    "-fx-background-radius: 10;" +
                    "-fx-padding: 8 10;";

    private PopupTheme() {}

    public static Alert createAlert(Alert.AlertType type, String title, String header, String content, ButtonType... buttons) {
        return createAlert(null, type, title, header, content, buttons);
    }

    public static Alert createAlert(Window owner,
                                    Alert.AlertType type,
                                    String title,
                                    String header,
                                    String content,
                                    ButtonType... buttons) {
        Alert alert = new Alert(type);
        if (owner != null) {
            alert.initOwner(owner);
            alert.initModality(Modality.WINDOW_MODAL);
        }
        alert.setTitle(title);
        alert.setHeaderText(header);
        alert.setContentText(content);
        if (buttons != null && buttons.length > 0) {
            alert.getButtonTypes().setAll(buttons);
        }
        styleAlert(alert);
        return alert;
    }

    public static Optional<ButtonType> showAndWait(Alert alert, Window owner) {
        boolean wasMaximized = owner instanceof Stage stage && stage.isMaximized();
        Optional<ButtonType> result = alert.showAndWait();
        if (owner instanceof Stage stage && stage.isShowing()) {
            stage.toFront();
            stage.requestFocus();
            if (wasMaximized && !stage.isMaximized()) {
                stage.setMaximized(true);
            }
        }
        return result;
    }

    public static void styleAlert(Alert alert) {
        DialogPane pane = alert.getDialogPane();
        pane.setGraphic(null);
        pane.setStyle(ROOT_STYLE);

        alert.setOnShown(e -> {
            Node header = pane.lookup(".header-panel");
            if (header != null) header.setStyle(HEADER_STYLE);

            Node headerLabel = pane.lookup(".header-panel .label");
            if (headerLabel instanceof Label label) label.setStyle(TITLE_STYLE.replace("24px", "20px"));

            Node contentLabel = pane.lookup(".content.label");
            if (contentLabel instanceof Label label) label.setStyle(LABEL_STYLE);

            for (ButtonType bt : pane.getButtonTypes()) {
                Node node = pane.lookupButton(bt);
                if (node instanceof Button button) {
                    ButtonBar.ButtonData data = bt.getButtonData();
                    if (bt == ButtonType.CANCEL || data == ButtonBar.ButtonData.CANCEL_CLOSE) {
                        button.setStyle(MUTED_BUTTON_STYLE);
                    } else if (data == ButtonBar.ButtonData.OK_DONE || data == ButtonBar.ButtonData.YES || data == ButtonBar.ButtonData.APPLY) {
                        button.setStyle(SECONDARY_BUTTON_STYLE);
                    } else {
                        button.setStyle(PRIMARY_BUTTON_STYLE);
                    }
                }
            }
        });
    }
}

package view.panel;

import javafx.scene.canvas.Canvas;
import javafx.scene.canvas.GraphicsContext;
import javafx.scene.control.ScrollPane;
import javafx.scene.Group;
import javafx.scene.layout.Region;
import javafx.scene.paint.Color;
import javafx.scene.text.Font;
import javafx.scene.text.TextAlignment;
import model.City;
import model.Game;
import model.Tile;
import model.enums.CargoType;
import model.enums.TileType;

/**
 * MinimapPanel — 2.5D isometric overview of the main map.
 *
 * Tiles are drawn as filled isometric diamonds using the same projection
 * formulas as MapPanel, scaled to fit within a dynamically-sized canvas.
 * The minimap size tracks the parent container so it shrinks and grows with
 * the window. A white rectangle shows the currently visible area; clicking
 * or dragging navigates the main ScrollPane.
 */
public class MinimapPanel extends Canvas {

    /** Fraction of the smaller parent dimension used for the minimap. */
    private static final double SIZE_FRACTION = 0.42;
    private static final int MIN_DIM = 300;
    private static final int MAX_DIM_CAP = 750;

    // Mirrors MapPanel constants
    private static final int MAIN_TW = 64;
    private static final int MAIN_TH = 32;
    private static final int MAIN_OY = 44; // WALL_H(24) + 20

    private final ScrollPane scroll;
    private final Group mapGroup;
    private final Canvas mainCanvas;

    private int maxDim = MAX_DIM_CAP; // current effective cap, updated by bindSize
    private double scale = 1.0;
    private int mmW = 1;
    private int mmH = 1;
    private Game currentGame;

    public MinimapPanel(ScrollPane scroll, Group mapGroup, Canvas mainCanvas) {
        super(1, 1);
        this.scroll = scroll;
        this.mapGroup = mapGroup;
        this.mainCanvas = mainCanvas;

        scroll.hvalueProperty().addListener((obs, o, n) -> redraw());
        scroll.vvalueProperty().addListener((obs, o, n) -> redraw());

        setOnMouseClicked(e -> navigate(e.getX(), e.getY()));
        setOnMouseDragged(e -> navigate(e.getX(), e.getY()));
    }

    /**
     * Bind the minimap size to a parent Region (e.g. the StackPane that
     * contains the scroll pane). The minimap is resized whenever the parent
     * resizes.
     */
    public void bindSize(Region parent) {
        parent.widthProperty().addListener((obs, o, n) -> onParentResized(n.doubleValue(), parent.getHeight()));
        parent.heightProperty().addListener((obs, o, n) -> onParentResized(parent.getWidth(), n.doubleValue()));
    }

    private void onParentResized(double parentW, double parentH) {
        int newMax = (int) Math.min(MAX_DIM_CAP,
                Math.max(MIN_DIM, Math.min(parentW, parentH) * SIZE_FRACTION));
        if (newMax != maxDim) {
            maxDim = newMax;
            if (currentGame != null)
                drawMinimap(currentGame);
        }
    }

    // ── Public API ───────────────────────────────────────────────────────────

    /** Full redraw — call when game state changes. */
    public void drawMinimap(Game game) {
        this.currentGame = game;
        int cols = game.getWidth();
        int rows = game.getHeight();

        double fullW = (cols + rows) * (MAIN_TW / 2.0) + MAIN_TW;
        double fullH = (cols + rows) * (MAIN_TH / 2.0) + MAIN_OY + 60;
        scale = maxDim / Math.max(fullW, fullH);

        mmW = (int) Math.ceil(fullW * scale);
        mmH = (int) Math.ceil(fullH * scale);
        setWidth(mmW + 2);
        setHeight(mmH + 2);

        redraw();
    }

    /** Refresh viewport rect after a zoom change. */
    public void refreshViewport() {
        redraw();
    }

    // ── Core render ──────────────────────────────────────────────────────────

    private void redraw() {
        if (currentGame == null || mmW <= 1)
            return;

        int cols = currentGame.getWidth();
        int rows = currentGame.getHeight();

        double mTW = MAIN_TW * scale;
        double mTH = MAIN_TH * scale;
        double mOX = rows * (mTW / 2.0) + 1;
        double mOY = MAIN_OY * scale + 1;

        GraphicsContext gc = getGraphicsContext2D();
        gc.setFill(Color.web("#87CEEB"));
        gc.fillRect(0, 0, mmW + 2, mmH + 2);

        // Isometric diamond tiles — same painter's order as MapPanel (y outer, x inner)
        for (int y = 0; y < rows; y++) {
            for (int x = 0; x < cols; x++) {
                Tile t = currentGame.getTile(x, y);
                gc.setFill(tileColor(t != null ? t.getType() : TileType.EMPTY));

                double cx = mOX + (x - y) * (mTW / 2.0);
                double cy = mOY + (x + y) * (mTH / 2.0);

                double[] xs = { cx, cx + mTW / 2.0, cx, cx - mTW / 2.0 };
                double[] ys = { cy, cy + mTH / 2.0, cy + mTH, cy + mTH / 2.0 };
                gc.fillPolygon(xs, ys, 4);
            }
        }

        drawCityDemandMarkers(gc, mTW, mTH, mOX, mOY);

        drawViewportRect(gc, rows);

        // gc.setStroke(Color.ORANGE);
        // gc.setLineWidth(1.0);
        // gc.strokeRect(0.5, 0.5, mmW + 1, mmH + 1);
    }

    private void drawCityDemandMarkers(GraphicsContext gc, double mTW, double mTH, double mOX, double mOY) {
        gc.setTextAlign(TextAlignment.CENTER);

        for (City city : currentGame.getCities()) {
            CargoType demand = city.getCurrentDemand();
            if (demand == null) continue;

            int tx = city.getCenter().getX();
            int ty = city.getCenter().getY();
            double cx = mOX + (tx - ty) * (mTW / 2.0);
            double cy = mOY + (tx + ty) * (mTH / 2.0) + mTH * 0.55;

            double radius = Math.max(4.0, Math.min(8.0, mTW * 0.33));

            gc.setFill(demandColor(demand));
            gc.fillOval(cx - radius, cy - radius, radius * 2, radius * 2);
            gc.setStroke(Color.rgb(0, 0, 0, 0.85));
            gc.setLineWidth(1.0);
            gc.strokeOval(cx - radius, cy - radius, radius * 2, radius * 2);

            String abbr = demand.abbreviation();
            gc.setFill(Color.WHITE);
            gc.setFont(Font.font("Monospace", Math.max(7.0, radius + 1.0)));
            gc.fillText(abbr, cx, cy + radius * 0.35);
        }
    }

    private static Color demandColor(CargoType type) {
        return switch (type) {
            case PASSENGERS -> Color.rgb(0, 130, 255);
            case WOOD -> Color.rgb(46, 139, 87);
            case IRON -> Color.rgb(120, 120, 120);
            case STEEL -> Color.rgb(90, 115, 140);
            case PAPER -> Color.rgb(205, 180, 120);
            case COAL -> Color.rgb(55, 55, 55);
            case OIL -> Color.rgb(35, 35, 35);
            case PLASTIC -> Color.rgb(170, 85, 215);
            case TEXTILE -> Color.rgb(225, 120, 60);
            case COTTON -> Color.rgb(235, 235, 235);
        };
    }

    private void drawViewportRect(GraphicsContext gc, int rows) {
        double zoom    = mapGroup.getScaleX();
        double canvasW = mainCanvas.getWidth();
        double canvasH = mainCanvas.getHeight();
        double vpW     = scroll.getViewportBounds().getWidth()  / zoom;
        double vpH     = scroll.getViewportBounds().getHeight() / zoom;

        double hRange = scroll.getHmax() - scroll.getHmin();
        double vRange = scroll.getVmax() - scroll.getVmin();
        double hFrac  = (hRange > 0) ? (scroll.getHvalue() - scroll.getHmin()) / hRange : 0;
        double vFrac  = (vRange > 0) ? (scroll.getVvalue() - scroll.getVmin()) / vRange : 0;

        double offX = hFrac * Math.max(0, canvasW - vpW);
        double offY = vFrac * Math.max(0, canvasH - vpH);

        // The minimap is a scaled copy of the isometric canvas, so the viewport
        // rectangle in canvas-pixel space maps directly to minimap-pixel space.
        double rX = 1 + offX * scale;
        double rY = 1 + offY * scale;
        double rW = Math.max(2, vpW * scale);
        double rH = Math.max(2, vpH * scale);

        gc.setStroke(Color.WHITE);
        gc.setLineWidth(1.5);
        gc.strokeRect(rX, rY, rW, rH);
    }

    // ── Navigation ───────────────────────────────────────────────────────────

    private void navigate(double mx, double my) {
        if (currentGame == null || scale <= 0)
            return;

        int rows = currentGame.getHeight();

        double mTW = MAIN_TW * scale;
        double mTH = MAIN_TH * scale;
        double mOX = rows * (mTW / 2.0) + 1;
        double mOY = MAIN_OY * scale + 1;

        // Invert minimap pixel → tile coordinate
        double relX = mx - mOX;
        double relY = my - mOY;
        double tx = (relX / (mTW / 2.0) + relY / (mTH / 2.0)) / 2.0;
        double ty = (relY / (mTH / 2.0) - relX / (mTW / 2.0)) / 2.0;

        // Forward-project tile → isometric canvas pixel
        double originX = rows * (MAIN_TW / 2.0);
        double cx = originX + (tx - ty) * (MAIN_TW / 2.0);
        double cy = MAIN_OY + (tx + ty) * (MAIN_TH / 2.0);

        double zoom = mapGroup.getScaleX();
        double canvasW = mainCanvas.getWidth();
        double canvasH = mainCanvas.getHeight();
        double vpW = scroll.getViewportBounds().getWidth() / zoom;
        double vpH = scroll.getViewportBounds().getHeight() / zoom;

        double scrollX = cx - vpW / 2.0;
        double scrollY = cy - vpH / 2.0;

        double rangeX = Math.max(0, canvasW - vpW);
        double rangeY = Math.max(0, canvasH - vpH);

        double hFrac = (rangeX > 0) ? Math.max(0, Math.min(1, scrollX / rangeX)) : 0;
        double vFrac = (rangeY > 0) ? Math.max(0, Math.min(1, scrollY / rangeY)) : 0;

        scroll.setHvalue(scroll.getHmin() + hFrac * (scroll.getHmax() - scroll.getHmin()));
        scroll.setVvalue(scroll.getVmin() + vFrac * (scroll.getVmax() - scroll.getVmin()));
    }

    // ── Tile colors ──────────────────────────────────────────────────────────

    private static Color tileColor(TileType type) {
        return switch (type) {
            case ROAD, CITY_ROAD -> Color.rgb(120, 120, 120);
            case CITY -> Color.rgb(230, 150, 50);
            case CITY_EMPTY -> Color.rgb(200, 130, 40);
            case FACILITY -> Color.rgb(160, 60, 180);
            case WATER -> Color.rgb(60, 140, 210);
            case FOREST -> Color.rgb(40, 110, 40);
            case BRIDGE -> Color.rgb(140, 100, 60);
            case STOP, CITY_STOP -> Color.rgb(220, 50, 50);
            default -> Color.rgb(100, 170, 60);
        };
    }
}

